// ===== a task on the map: the pane names the task, how far it is, its status filters, its rooms (only when more than one); the pens carry the state =====
const POLY = JSON.parse(fs.readFileSync(path.join(__dirname, 'nvpoly.json'), 'utf8'));
const SHIELD = 'M12 3 5 6v6c0 4.5 3 7.5 7 9 4-1.5 7-4.5 7-9V6l-7-3Z', PENI = 'M5 5h14v14H5zM9.7 5v14M14.3 5v14';
const ST = { done: ['#4F9E62', 'Done'], part: ['#BFE0C6', 'Under way'], todo: ['#8DB4E8', 'To do'], look: ['#D9A441', 'Needs a look'] };
// a pane sized to what it holds, under the bar, never past the bottom edge
const paneFit = (head, body) => panel(head, body).replace("top: 12px; bottom: 12px;", 'top: ' + LT + 'px; max-height: calc(100% - ' + (LT + 12) + 'px);').replace('flex: 1 1 auto; min-height: 0; overflow: hidden; padding: 0 16px 16px;', 'flex: 0 1 auto; min-height: 0; overflow: hidden; padding: 0 16px 16px;');
const chipF = (col, l, n, on) => '<span style="' + st({ display: 'inline-flex', alignItems: 'center', gap: '7px', height: '34px', padding: '0 11px', borderRadius: '10px', background: on ? K.press : '#FFFFFF', boxShadow: 'inset 0 0 0 ' + (on ? '1.5px ' + K.ink : '1px ' + K.line), fontSize: '13px', fontWeight: on ? 600 : 500, whiteSpace: 'nowrap' }) + '"><i style="width: 10px; height: 10px; border-radius: 3px; background: ' + col + ';"></i>' + l + ' <b style="font-weight: 600;">' + n + '</b></span>';
const pbar = (parts) => '<div style="display: flex; gap: 2px; height: 8px; border-radius: 4px; overflow: hidden; margin: 10px 0 4px;">' + parts.map((p) => '<i style="flex: ' + p[0] + '; background: ' + p[1] + ';"></i>').join('') + '</div>';
const filters = (items) => '<div style="display: flex; flex-wrap: wrap; gap: 6px; margin-top: 12px;">' + items.map((x) => chipF(x[0], x[1], x[2], x[3])).join('') + '</div>';
const pbox = (inner) => '<div style="padding: 14px 16px; background: #FFFFFF; border: 1px solid ' + K.line + '; border-radius: 16px;">' + inner + '</div>';
const twoBtns = (a, b) => '<div style="display: flex; gap: 8px; margin-top: 14px;">' + fbtn(a) + fbtn(b) + '</div>';
// the nursery pens, coloured by the rule
const nState = (rid, c) => { const L1 = c[0], k = +c.slice(1); if (rid === 'n1') { if (L1 === 'A' || k <= 10) return 'done'; if (k === 11) return 'part'; if (k === 12) return 'look'; return 'todo'; } if (L1 === 'A' && k <= 8) return 'done'; if (L1 === 'A' && k === 9) return 'part'; return 'todo'; };
const penSvg = (hot) => '<svg viewBox="0 0 950 830" style="position: absolute; inset: 0; width: 950px; height: 830px; pointer-events: none;">' + ['n1', 'n2'].map((id) => POLY[id].map((p) => { const s = nState(id, p[0]), on = hot && hot === id + p[0]; return '<polygon points="' + p[1].map((q) => q.join(',')).join(' ') + '" fill="' + ST[s][0] + '" stroke="' + (on ? K.ink : '#FFFFFF') + '" stroke-width="' + (on ? 2 : 0.8) + '"></polygon>'; }).join('')).join('') + '</svg>';
const fadeAll = '<div style="position: absolute; inset: 0; background: rgba(246,247,241,.62);"></div>';
const ctr = (id, code) => { const p = POLY[id].find((x) => x[0] === code)[1]; return [p.reduce((a, q) => a + q[0], 0) / 4, p.reduce((a, q) => a + q[1], 0) / 4]; };
const nbar = () => card({ left: '12px', right: '12px', top: BT + 'px' }, sq(I.back) + '<span style="' + st({ display: 'inline-flex', alignItems: 'center', gap: '9px', height: '40px', padding: '0 10px 0 6px' }) + '"><span style="' + st({ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', width: '32px', height: '32px', borderRadius: '9px', background: K.press }) + '">' + ic('M4 4h7v7H4zM13 4h7v7h-7zM4 13h7v7H4zM13 13h7v7h-7z', 17) + '</span>' + t('Nursery', { fontSize: '17px', fontWeight: 600 }) + '</span>' + sep + btn(I.pig, 'Pigs', { n: '958' }) + btn(I.tool, 'Devices') + '<span style="flex: 1;"></span>' + btn(I.select, 'Select'), { display: 'flex', alignItems: 'center', gap: '2px', padding: '0 8px', height: '56px' });
const tabsV = () => tabsStrip('Farm view').replace('Treatment RX-25G009', 'PRRS vaccine · Batch 30, 31');

const vaxPane = () => paneFit(thead({ title: 'PRRS vaccine', sub: 'Batch 30 and 31 · 2 rooms', ico: SHIELD, icoBg: K.greenT, icoInk: K.green }),
  pbox('<div style="display: flex; align-items: baseline; justify-content: space-between;">' + t('416 of 958 weaners', { fontSize: '17px', fontWeight: 600 }) + mu('44 of 104 pens done') + '</div>' + pbar([[44, ST.done[0]], [2, ST.part[0]], [1, ST.look[0]], [57, ST.todo[0]]]) + filters([[ST.done[0], 'Done', '44'], [ST.part[0], 'Under way', '2'], [ST.todo[0], 'To do', '57'], [ST.look[0], 'Needs a look', '1']])) +
  sec('Rooms', 'pens left') + box([{ h: ic('M4 10 12 4l8 6v10H4V10Z', 16, 1.8, K.muted) + t('Nursery 1', { flex: 1, fontWeight: 500 }) + mu('16 left') + ic(I.chev, 14, 1.8, K.faint) }, { h: ic('M4 10 12 4l8 6v10H4V10Z', 16, 1.8, K.muted) + t('Nursery 2', { flex: 1, fontWeight: 500 }) + mu('44 left') + ic(I.chev, 14, 1.8, K.faint) }]) +
  twoBtns(ic(SC2.ext, 15) + '&nbsp; Open page', ic(I.log, 16) + '&nbsp; Log'));
const rxPane = () => paneFit(thead({ title: 'Treatment RX-25G009', sub: 'Amoxicillin · dose 2 of 3 today' }),
  pbox('<div style="display: flex; align-items: baseline; justify-content: space-between;">' + t('2 of 4 sows given', { fontSize: '17px', fontWeight: 600 }) + mu('next dose 08:30') + '</div>' + pbar([[2, ST.done[0]], [1, '#3972B7'], [1, ST.look[0]]]) + filters([[ST.done[0], 'Given', '2'], ['#3972B7', 'Due', '1'], [ST.look[0], 'Skipped', '1']])) +
  twoBtns(ic(SC2.ext, 15) + '&nbsp; Open page', ic(I.log, 16) + '&nbsp; Log'));
const B11 = ctr('n1', 'B11');

frames.f1 = frames.t1;
frames.f1.cap = 'The task page in its own tab keeps the full list: every sow, every dose, notes. Show in Farm view opens the map version.';
frames.f2 = { bg: 'tx', cap: 'One room: the pane is the task\'s header, its progress, and its status filters. No list: the map is the list. Each pen takes one state: B15 and B20 given, D40 due, D41 amber because a dose was skipped.', html: () => tabsStrip('Farm view') + fbar() + rxPane() + vctl };
frames.f3 = { bg: 'tx', cap: 'Click a sow\'s pen: the pane goes one level down to her. Her part of the task, her log, her record. ‹ returns to the task.', html: () => frames.t4.html() };
frames.f4 = { bg: 'nv', cap: 'Two rooms: the same pane, plus Rooms, because the task spans more than one. Each room shows the pens left; clicking it flies there. Group pens follow the rule: full green done, pale green under way, blue to do, amber needs a look.', html: () => tabsV() + fadeAll + penSvg() + nbar() + vaxPane() + vctl };
frames.f5 = { bg: 'nv', cap: 'Hover a pen: its numbers live here, never on the map.', html: () => tabsV() + fadeAll + penSvg('n1B11') + nbar() + vaxPane() + vctl + card({ left: (B11[0] + 16) + 'px', top: (B11[1] + 14) + 'px', width: '228px' }, '<div style="padding: 10px 12px;"><div style="display: flex; justify-content: space-between; align-items: baseline;">' + t('Pen B11', { fontWeight: 600 }) + mu('Nursery 1', { fontSize: '12px' }) + '</div><div style="height: 1px; background: ' + K.line + '; margin: 8px 0;"></div><div style="display: flex; justify-content: space-between; font-size: 13px;"><span>Vaccinated</span><b style="font-weight: 600;">6 of 9</b></div><div style="display: flex; justify-content: space-between; font-size: 13px; margin-top: 4px;"><span>To do</span><b style="color: #3972B7; font-weight: 600;">3</b></div><div style="margin-top: 8px; font-size: 12px; color: ' + K.muted + ';">Click for the pen</div></div>') };
frames.f6 = { bg: 'nv', cap: 'Click a group pen: the pen\'s page. Its numbers, its tagged pigs as rows, the untagged ones as one counted row, its log.', html: () => tabsV() + fadeAll + penSvg('n1B11') + nbar() + vctl + paneFit(thead({ back: 'PRRS vaccine', title: 'Pen B11', sub: 'Nursery 1 · 9 weaners · Batch 30', ico: PENI, icoBg: K.press, icoInk: K.ink }),
  pbox('<div style="display: flex; align-items: baseline; justify-content: space-between;">' + t('6 of 9 vaccinated', { fontSize: '16px', fontWeight: 600 }) + mu('3 to do') + '</div>' + pbar([[6, ST.done[0]], [3, ST.todo[0]]])) +
  sec('Pigs') + box([{ h: dose('d') + '<span style="flex: 1; display: flex; flex-direction: column;">' + t('310412', { fontWeight: 600 }) + mu('Vaccinated 08:10 · G.H', { fontSize: '12.5px' }) + '</span>' + ic(I.chev, 14, 1.8, K.faint) }, { h: dose('w') + '<span style="flex: 1; display: flex; flex-direction: column;">' + t('310418', { fontWeight: 600 }) + mu('To do', { fontSize: '12.5px' }) + '</span>' + ic(I.chev, 14, 1.8, K.faint) }, { h: '<span style="display: grid; place-items: center; width: 22px; height: 22px; border-radius: 99px; background: ' + K.press + '; font-size: 11px; font-weight: 700;">7</span><span style="flex: 1; display: flex; flex-direction: column;">' + t('7 untagged', { fontWeight: 600 }) + mu('5 vaccinated, 2 to do · counted at the pen', { fontSize: '12.5px' }) + '</span>' }]) +
  sec('Pen log') + box([['08:10', 'Vaccinated 6 of 9', 'G.H'], ['Mon', 'Moved in, 9 weaners', 'Batch 30']].map((r) => ({ h: t(r[0], { width: '52px', fontSize: '12.5px', color: K.muted }) + '<span style="flex: 1; display: flex; flex-direction: column;">' + t(r[1], { fontSize: '13.5px' }) + mu(r[2], { fontSize: '12px' }) + '</span>' })))) };
